const API = (() => {
  async function request(method, path, { params, body } = {}) {
    let url = path;
    if (params) {
      const qs = new URLSearchParams();
      for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== null && v !== '') qs.set(k, v);
      const s = qs.toString();
      if (s) url += (path.includes('?') ? '&' : '?') + s;
    }
    let res;
    try {
      res = await fetch(url, {
        method,
        headers: body ? { 'Content-Type': 'application/json' } : undefined,
        body: body ? JSON.stringify(body) : undefined,
      });
    } catch (e) {
      const err = new Error('无法连接服务器，请确认后端已启动');
      err.network = true;
      throw err;
    }
    let payload = null;
    try { payload = await res.json(); } catch (e) { /* ignore */ }
    if (!res.ok || !payload || payload.code !== 'SUCCESS') {
      const err = new Error((payload && payload.message) || '请求失败（HTTP ' + res.status + '）');
      err.status = res.status;
      err.code = payload ? payload.code : undefined;
      throw err;
    }
    return payload.data;
  }
  return {
