  /* ---------- 确认弹窗（Promise<boolean>） ---------- */
  function confirmDialog(opts) {
    opts = opts || {};
    return new Promise(function (resolve) {
      var overlay = el('div', 'modal-overlay');
      var modal = el('div', 'modal');
      modal.setAttribute('role', 'alertdialog');
