trackX(p): gridline left position within track area:
```js
    function trackX(p) {
      return 'calc(var(--name-w) + var(--gap) + (100% - var(--name-w) - var(--gap) - var(--val-w) - var(--gap)) * ' + (p / 100) + ')';
    }
```
Gridlines/tick labels positioned relative to .bar-plot (full width). Track spans from (name-w + gap) to (100% - val-w - gap). So x = nameW+gap + p/100 * (100% - nameW - 2gap - valW). As calc: `calc(var(--name-w) + var(--gap) + (100% - var(--name-w) - 2 * var(--gap) - var(--val-w)) * 0.25)`. Gridline left at that x minus 0.5px for hairline center — negligible.

Careful: .bar-grid is absolute inset 0 (right 0), .bar-ticks too. trackX used in both. tick translateX(-50%) centers label. Gridline at exact track edge. For 0% label translate -50% → half outside left — acceptable? Leftmost tick "0%" would extend left beyond plot into name column area? Name column width 132 with its own padding; tick at track start (x=146) translated -50% → starts ~130 → overlaps name column slightly. Name column content ends at ~132+gap. "0%" width ~16px → from 138 to 154; name area right edge is 146. Slight overlap into name column zone but name text usually shorter; visually fine, and labels are muted 11px. Acceptable; alternatively left-align 0 tick: special-case: if p===0 → translateX(0); if p===100 → translateX(-100%). Nice refinement — do that.

showChartTip(e, rt, row): tooltip singleton:
```js
    let tip = null;
    function ensureTip() {
      if (!tip) { tip = el('div', 'chart-tooltip'); tip.setAttribute('role', 'tooltip'); document.body.appendChild(tip); }
      return tip;
    }
    function fillTip(rt) {
      clear(tip);
      tip.appendChild(el('div', 'tt-title', (rt.name || '') + (rt.code ? '（' + rt.code + '）' : '')));
      const r1 = el('div', 'tt-row'); r1.appendChild(el('span', 'k', '总房数')); r1.appendChild(el('span', 'v', fmt.num(rt.total))); tip.appendChild(r1);
      const r2 = el('div', 'tt-row'); r2.appendChild(el('span', 'k', '已售间数')); r2.appendChild(el('span', 'v', fmt.num(rt.sold))); tip.appendChild(r2);
      const r3 = el('div', 'tt-row'); r3.appendChild(el('span', 'k', '入住率')); r3.appendChild(el('span', 'v', fmt.pct(rt.rate))); tip.appendChild(r3);
    }
    function showChartTip(e, rt, row) {
      const t = ensureTip(); fillTip(rt);
      moveTip(e, t);
    }
    function moveTip(e, t) {
      const pad = 14;
      let x = e.clientX + pad, y = e.clientY + pad;
      const rect = t.getBoundingClientRect();
      if (x + rect.width > window.innerWidth - 8) x = e.clientX - rect.width - pad;
      if (y + rect.height > window.innerHeight - 8) y = e.clientY - rect.height - pad;
      t.style.left = x + 'px'; t.style.top = y + 'px';
    }
