  var DEMO_PHONES = ['13800138001', '13800138002', '13800138003', '13800138004'];

  var ordersView = {
    state: { items: [], expanded: {} },
    loaded: false,
    pendingQuery: null,
    els: null,

    ensure: function () {
      if (!this.loaded) {
        this.cacheEls();
        this.bind();
        this.loaded = true;
      }
      if (this.pendingQuery) {
        var q = this.pendingQuery;
        this.pendingQuery = null;
        this.els.input.value = q;
        this.search();
      }
