        node.style.setProperty('--tl-color', toneInk(meta.tone));
        node.appendChild(el('div', 'tl-title', meta.icon + ' ' + meta.label));
        if (l.remark) node.appendChild(el('div', 'tl-remark', l.remark));
        node.appendChild(el('div', 'tl-meta',
