cd /Users/fangsanpi/hotel-booking-system/src/main/resources/static && node -e "
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const js = fs.readFileSync('js/app.js', 'utf8') + fs.readFileSync('js/ui.js', 'utf8');
// JS 中以 \$('#xxx') 形式引用的 ID
const jsIds = new Set();
for (const m of js.matchAll(/\\\$\('#([a-z0-9-]+)'\)/g)) jsIds.add(m[1]);
const htmlIds = new Set();
for (const m of html.matchAll(/id=\"([a-z0-9-]+)\"/g)) htmlIds.add(m[1]);
const missing = [...jsIds].filter(id => !htmlIds.has(id));
console.log('JS 引用 ID 数:', jsIds.size, '| HTML 定义 ID 数:', htmlIds.size);
console.log('缺失 ID:', missing.length ? missing : '无');
// 静态 HTML 中引用的 ID 是否都被 JS 使用或被 API 契约覆盖（fd-tbody/fd-occupancy-tbody 等由 JS 使用）
const unused = [...htmlIds].filter(id => !jsIds.has(id));
console.log('HTML 中未被 JS 引用的 ID（应仅含主题按钮等自管理项）:', unused);
"

