1	/**
2	 * 栖云酒店预订管理系统 · 前端 SPA 逻辑
3	 * - URL hash 路由：#/booking（预订）、#/orders（订单查询）、#/frontdesk（前台管理）
4	 * - 所有接口数据渲染仅使用 textContent / createElement（无 innerHTML 注入面）
5	 * - 图表遵循 dataviz 规范：单序列 slot-1 蓝、薄条形、值标注 + 表格视图、悬停提示
6	 */
7	(function () {
8	  'use strict';
9	
10	  var UI = window.UI;
11	  var el = UI.el, clear = UI.clear, fmt = UI.fmt;
12	  var badge = UI.badge, Toast = UI.Toast, confirmDialog = UI.confirmDialog;
13	  var copyText = UI.copyText, setBusy = UI.setBusy;
14	  var operatorLabel = UI.operatorLabel, statusOf = UI.statusOf, toneInk = UI.toneInk;
15	
16	  var $ = function (sel, root) { return (root || document).querySelector(sel); };
17	  var $$ = function (sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); };
18	
19	  var PHONE_RE = /^1\d{10}$/;
20	  var MAX_NIGHTS = 30;   // 与后端 app.booking.max-stay-nights 一致
21	  var MAX_ROOMS = 3;     // 预订页间数上限（后端上限 5，演示取 3）
22	
23	  /* ================= 通用工具 ================= */
24	
25	  function pad2(n) { return String(n).padStart(2, '0'); }
26	  function dateStr(d) {
27	    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
28	  }
29	  function addDays(dateStrLike, n) {
30	    var d = UI.parseDate(dateStrLike);
31	    if (!d) return dateStrLike;
32	    d.setDate(d.getDate() + n);
33	    return dateStr(d);
34	  }
35	  function nightsBetween(a, b) {
36	    var da = UI.parseDate(a), db = UI.parseDate(b);
37	    if (!da || !db) return 0;
38	    return Math.round((db - da) / 86400000);
39	  }
40	  function newRequestId() {
41	    try {
42	      if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
43	    } catch (e) { /* fall through */ }
44	    return 'r-' + Date.now().toString(36) + '-' +
45	      Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 10);
46	  }
47	  function clamp(v, lo, hi) { return Math.min(hi, Math.max(lo, v)); }
48	
49	  function emptyState(ico, title, hint, chips) {
50	    var wrap = el('div', 'empty');
51	    wrap.appendChild(el('div', 'empty-ico', ico));
52	    wrap.appendChild(el('div', 'empty-title', title));
53	    if (hint) wrap.appendChild(el('div', 'empty-hint', hint));
54	    if (chips && chips.length) {
55	      var row = el('div', 'empty-chips');
56	      chips.forEach(function (c) {
57	        var chip = el('button', 'chip chip--click', c.label);
58	        chip.type = 'button';
59	        chip.addEventListener('click', c.onClick);
60	        row.appendChild(chip);
61	      });
62	      wrap.appendChild(row);
63	    }
64	    return wrap;
65	  }
66	
67	  function setFieldError(input, msg) {
68	    if (!input) return;
69	    input.setAttribute('aria-invalid', 'true');
70	    var box = input.parentNode;
71	    var err = box ? box.querySelector('.field-error') : null;
72	    if (!err) {
73	      err = el('div', 'field-error', msg);
74	      if (box) box.appendChild(err);
75	    } else {
76	      err.textContent = msg;
77	    }
78	    input.focus();
79	  }
80	  function clearFieldError(input) {
81	    if (!input) return;
82	    input.removeAttribute('aria-invalid');
83	    var box = input.parentNode;
84	    var err = box ? box.querySelector('.field-error') : null;
85	    if (err) err.parentNode.removeChild(err);
86	  }
87	
88	  function summaryRow(rows, k, v) {
89	    var r = el('div', 'summary-row');
90	    r.appendChild(el('span', 'k', k));
91	    r.appendChild(el('span', 'v', v));
92	    rows.appendChild(r);
93	  }
94	
95	  /* ================= 主题切换 ================= */
96	
97	  var THEME_KEY = 'qiyun-theme';
98	  var themeToggle = $('#theme-toggle');
99	
100	  function effectiveTheme() {
101	    var forced = document.documentElement.getAttribute('data-theme');
102	    if (forced) return forced;
103	    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) return 'dark';
104	    return 'light';
105	  }
106	  function syncThemeIcon() {
107	    var dark = effectiveTheme() === 'dark';
108	    themeToggle.textContent = dark ? '☀️' : '🌙';
109	    themeToggle.title = dark ? '切换为浅色主题' : '切换为深色主题';
110	  }
111	  function initTheme() {
112	    try {
113	      var stored = localStorage.getItem(THEME_KEY);
114	      if (stored === 'dark' || stored === 'light') {
115	        document.documentElement.setAttribute('data-theme', stored);
116	      }
117	    } catch (e) { /* 隐私模式等场景忽略 */ }
118	    syncThemeIcon();
119	    themeToggle.addEventListener('click', function () {
120	      var next = effectiveTheme() === 'dark' ? 'light' : 'dark';
121	      try { localStorage.setItem(THEME_KEY, next); } catch (e) { /* ignore */ }
122	      document.documentElement.setAttribute('data-theme', next);
123	      syncThemeIcon();
124	    });
125	    if (window.matchMedia) {
126	      window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function () {
127	        if (!document.documentElement.getAttribute('data-theme')) syncThemeIcon();
128	      });
129	    }
130	  }
131	
132	  /* ================= 视图一：预订房间 ================= */
133	
134	  var booking = {
135	    state: {
136	      step: 1,
137	      availability: [],
138	      selected: null,
139	      requestId: null,
140	      form: { name: '', phone: '', idNo: '', count: 1 },
141	      fields: null,
142	      result: null
143	    },
144	    loaded: false,
145	    els: null,
146	
147	    ensure: function () {
148	      if (!this.loaded) {
149	        this.cacheEls();
150	        this.initDates();
151	        this.bind();
152	        this.loaded = true;
153	        this.query({ first: true });
154	      }
155	    },
156	
157	    cacheEls: function () {
158	      this.els = {
159	        checkIn: $('#bk-checkin'),
160	        checkOut: $('#bk-checkout'),
161	        nights: $('#bk-nights'),
162	        queryBtn: $('#bk-query'),
163	        listWrap: $('#bk-list-wrap'),
164	        list: $('#bk-list'),
165	        step2: $('#bk-step2'),
166	        step3: $('#bk-step3')
167	      };
168	    },
169	
170	    initDates: function () {
171	      var today = new Date();
172	      var t = dateStr(today);
173	      this.els.checkIn.value = t;
174	      this.els.checkIn.min = t;
175	      this.els.checkOut.value = addDays(t, 1);
176	      this.els.checkOut.min = addDays(t, 1);
177	      this.updateNights();
178	    },
179	
180	    bind: function () {
181	      var self = this;
182	      this.els.checkIn.addEventListener('change', function () {
183	        var inD = self.els.checkIn.value;
184	        if (!inD) return;
185	        self.els.checkOut.min = addDays(inD, 1);
186	        var nights = nightsBetween(inD, self.els.checkOut.value);
187	        if (nights < 1) {
188	          self.els.checkOut.value = addDays(inD, 1);
189	          Toast.info('离店日期已自动调整为入住次日');
190	        } else if (nights > MAX_NIGHTS) {
191	          self.els.checkOut.value = addDays(inD, MAX_NIGHTS);
192	          Toast.info('单次入住最长 ' + MAX_NIGHTS + ' 晚，离店日期已调整');
193	        }
194	        self.updateNights();
195	        if (self.state.step === 2) self.renderStep2();
196	      });
197	      this.els.checkOut.addEventListener('change', function () {
198	        var inD = self.els.checkIn.value;
199	        var nights = nightsBetween(inD, self.els.checkOut.value);
200	        if (nights < 1) {
201	          self.els.checkOut.value = addDays(inD, 1);
202	          Toast.info('离店日期必须晚于入住日期，已自动调整');
203	        } else if (nights > MAX_NIGHTS) {
204	          self.els.checkOut.value = addDays(inD, MAX_NIGHTS);
205	          Toast.info('单次入住最长 ' + MAX_NIGHTS + ' 晚，离店日期已调整');
206	        }
207	        self.updateNights();
208	        if (self.state.step === 2) self.renderStep2();
209	      });
210	      this.els.queryBtn.addEventListener('click', function () { self.query(); });
211	    },
212	
213	    updateNights: function () {
214	      var n = Math.max(0, nightsBetween(this.els.checkIn.value, this.els.checkOut.value));
215	      this.els.nights.textContent = String(n);
216	    },
217	
218	    query: function (opts) {
219	      opts = opts || {};
220	      var self = this;
221	      var inD = this.els.checkIn.value;
222	      var outD = this.els.checkOut.value;
223	      if (!inD || !outD) { Toast.info('请先选择入住与离店日期'); return; }
224	      if (nightsBetween(inD, outD) < 1) {
225	        Toast.error('离店日期必须晚于入住日期');
226	        return;
227	      }
228	      setBusy(this.els.queryBtn, true, '查询中…');
229	      if (!opts.quiet) this.els.listWrap.classList.add('is-refreshing');
230	      API.availability(inD, outD).then(function (data) {
231	        self.state.availability = data || [];
232	        self.renderAvailability(null);
233	      }).catch(function (e) {
234	        self.state.availability = [];
235	        self.renderAvailability(e.message);
236	        if (!opts.quiet) Toast.error(e.message);
237	      }).finally(function () {
238	        setBusy(self.els.queryBtn, false);
239	        self.els.listWrap.classList.remove('is-refreshing');
240	      });
241	    },
242	
243	    /** 下单成功后静默刷新房态余量（保留上一帧、不打扰） */
244	    refreshAvailabilityQuiet: function () {
245	      var self = this;
246	      API.availability(this.els.checkIn.value, this.els.checkOut.value).then(function (data) {
247	        self.state.availability = data || [];
248	        self.renderAvailability(null);
249	      }).catch(function () { /* 静默失败 */ });
250	    },
251	
252	    renderAvailability: function (errorMsg) {
253	      clear(this.els.list);
254	      var self = this;
255	      if (!this.state.availability.length) {
256	        this.els.list.appendChild(errorMsg
257	          ? emptyState('📡', '查询失败', errorMsg, null)
258	          : emptyState('🏨', '该日期区间暂无可售房型', '换个日期再试试，或返回默认日期查询', null));
259	        return;
260	      }
261	      this.state.availability.forEach(function (a) {
262	        self.els.list.appendChild(self.renderRoomCard(a));
263	      });
264	    },
265	
266	    renderRoomCard: function (a) {
267	      var self = this;
268	      var soldOut = a.remaining <= 0;
269	      var card = el('article', 'room-card' + (soldOut ? ' room-card--sold' : ''));
270	
271	      var head = el('div', 'room-head');
272	      head.appendChild(el('h3', 'room-name', a.name || '—'));
273	      if (a.code) head.appendChild(el('span', 'tag tag-code', a.code));
274	      var stock = soldOut
275	        ? el('span', 'chip chip--danger', '满房')
276	        : el('span', 'chip chip--accent', '剩 ' + a.remaining + ' 间');
277	      stock.classList.add('room-stock');
278	      head.appendChild(stock);
279	      card.appendChild(head);
280	
281	      if (a.amenities) {
282	        var am = el('div', 'room-amenities');
283	        String(a.amenities).split('·').map(function (s) { return s.trim(); })
284	          .filter(Boolean)
285	          .forEach(function (t) { am.appendChild(el('span', 'amenity', t)); });
286	        card.appendChild(am);
287	      }
288	
289	      var list = el('div', 'night-list');
290	      (a.priceDetails || []).forEach(function (d) {
291	        var row = el('div', 'night-row');
292	        var wk = fmt.isWeekendNight(d.date);
293	        var hiked = Number(d.price) > Number(a.basePrice);
294	        if (wk || hiked) row.classList.add('night-row--weekend');
295	        var left = el('span', 'night-date', fmt.date(d.date));
296	        left.appendChild(el('span', 'night-dow', ' ' + fmt.weekday(d.date)));
297	        var right = el('span', 'night-right');
298	        if (wk) right.appendChild(el('span', 'tag tag-weekend', '周末价'));
299	        else if (hiked) right.appendChild(el('span', 'tag tag-weekend', '调价'));
300	        right.appendChild(el('span', 'night-price', fmt.money(d.price)));
301	        row.appendChild(left);
302	        row.appendChild(right);
303	        list.appendChild(row);
304	      });
305	      card.appendChild(list);
306	
307	      var foot = el('div', 'room-foot');
308	      var price = el('span', 'price-total num', fmt.money(a.totalPrice));
309	      price.appendChild(el('span', 'price-cap', ' / ' + a.nights + ' 晚 · 1 间'));
310	      foot.appendChild(price);
311	      var btn = el('button', 'btn btn-primary');
312	      if (soldOut) {
313	        btn.textContent = '已满房';
314	        btn.disabled = true;
315	      } else {
316	        btn.textContent = '预订';
317	        btn.addEventListener('click', function () { self.openStep2(a); });
318	      }
319	      foot.appendChild(btn);
320	      card.appendChild(foot);
321	      return card;
322	    },
323	
324	    openStep2: function (a) {
325	      this.state.selected = a;
326	      this.state.step = 2;
327	      this.state.form.count = clamp(Number(this.state.form.count) || 1, 1, MAX_ROOMS);
328	      this.renderStep2();
329	      this.els.listWrap.hidden = true;
330	      this.els.step2.hidden = false;
331	      this.els.step3.hidden = true;
332	      window.scrollTo({ top: 0, behavior: 'smooth' });
333	    },
334	
335	    backToStep1: function () {
336	      this.state.step = 1;
337	      this.els.step2.hidden = true;
338	      this.els.step3.hidden = true;
339	      this.els.listWrap.hidden = false;
340	      window.scrollTo({ top: 0, behavior: 'smooth' });
341	    },
342	
343	    renderStep2: function () {
344	      var self = this;
345	      var a = this.state.selected;
346	      if (!a) return;
347	      clear(this.els.step2);
348	      var grid = el('div', 'panel-grid');
349	
350	      /* ---- 摘要卡 ---- */
351	      var sc = el('div', 'card');
352	      var t1 = el('div', 'panel-title');
353	      t1.appendChild(el('span', 'step-num', '2'));
354	      t1.appendChild(el('span', null, '确认预订信息'));
355	      sc.appendChild(t1);
356	      var rows = el('div', 'summary-rows');
357	      summaryRow(rows, '房型', (a.name || '') + '（' + (a.code || '') + '）');
358	      summaryRow(rows, '入住', fmt.date(this.els.checkIn.value) + ' ' + fmt.weekday(this.els.checkIn.value));
359	      summaryRow(rows, '离店', fmt.date(this.els.checkOut.value) + ' ' + fmt.weekday(this.els.checkOut.value));
360	      summaryRow(rows, '晚数', a.nights + ' 晚');
361	      var countRow = el('div', 'summary-row');
362	      countRow.appendChild(el('span', 'k', '间数'));
363	      var sel = el('select', 'input input-sm select');
364	      for (var i = 1; i <= MAX_ROOMS; i++) {
365	        var o = el('option', null, i + ' 间');
366	        o.value = String(i);
367	        if (i === Number(this.state.form.count)) o.selected = true;
368	        sel.appendChild(o);
369	      }
370	      countRow.appendChild(sel);
371	      rows.appendChild(countRow);
372	      sc.appendChild(rows);
373	
374	      var nl = el('div', 'night-list');
