const fs = require('fs');
const css = fs.readFileSync('css/style.css', 'utf8');
const js = fs.readFileSync('js/app.js', 'utf8') + fs.readFileSync('js/ui.js', 'utf8');
const html = fs.readFileSync('index.html', 'utf8');
const classes = new Set();
// JS: el(tag, 'class') / el(tag, 'a b' + cond) 等静态类名
for (const m of js.matchAll(/el\([^,]+,\s*'([^']*)'/g)) m[1].split(/\s+/).filter(Boolean).forEach(c => classes.add(c));
for (const m of js.matchAll(/classList\.(?:add|toggle)\('([^']+)'/g)) classes.add(m[1]);
// HTML 静态 class
for (const m of html.matchAll(/class=\"([^\"]+)\"/g)) m[1].split(/\s+/).filter(Boolean).forEach(c => classes.add(c));
const missing = [];
for (const c of classes) {
  const re = new RegExp('\\\\.' + c.replace(/-/g, '\\\\-') + '(?![a-zA-Z0-9_-])');
  if (!re.test(css)) missing.push(c);
}
// 排除 JS 条件拼接的动态类（room-card--sold / order-card--open / night-row--weekend / toast--* / badge--* / chip--* 等以 -- 变体拼接）
const dynamic = new Set(['room-card','order-card','night-row','toast','badge','chip','btn-danger-solid']);
const real = missing.filter(c => !(c.includes('--') && [...dynamic].some(d => c.startsWith(d + '--') || c === d)));
console.log('引用类名总数:', classes.size, '| 未定义类名:', missing.length ? missing : '无', '| 动态拼接排除后:', real.length ? real : '无');
" && node --check js/api.js && node --check js/ui.js && node --check js/app.js && echo "=== node --check: ALL PASS ===" && ls -laR . | grep -v "^total"

