/* ==========================================================================
   栖云酒店预订管理系统 · 前端样式
   设计依据：dataviz skill 参考色板（light/dark 双主题，同一色阶两步）
   单序列图表仅使用 slot-1 蓝（--series-1）；状态徽标使用状态色（始终图标+文字）
   ========================================================================== */

/* ---------- Design tokens：浅色（默认） ---------- */
:root {
  color-scheme: light;

  /* 表面与墨水 */
  --page: #f9f9f7;
  --surface-1: #fcfcfb;
  --surface-2: #f4f3ef;
  --ink: #0b0b0b;
  --ink-2: #52514e;
  --ink-3: #898781;
  --grid: #e1e0d9;
  --base: #c3c2b7;
  --border: rgba(11, 11, 11, 0.10);
  --border-strong: rgba(11, 11, 11, 0.20);

  /* 品牌强调（= 分类色 slot 1 蓝） */
  --accent: #2a78d6;
  --accent-strong: #256abf;
  --accent-soft: #e8f0fb;
  --accent-ink: #1c5cab;
  --focus-ring: rgba(42, 120, 214, 0.30);

  /* 图表 */
  --series-1: #2a78d6;
  --track: #cde2fb;          /* 蓝色阶 step 100（同色浅阶轨道） */

  /* 状态色（固定，不随主题换色相） */
  --good: #0ca30c;
  --warning: #fab219;
  --serious: #ec835a;
  --critical: #d03b3b;
  --success-ink: #006300;

  /* 状态徽标（浅色调底 + 深色文字，均通过 WCAG AA 文本对比） */
  --bdg-amber-bg: #fdf1d0;   --bdg-amber-ink: #7a5a00;
  --bdg-blue-bg: #e8f0fb;    --bdg-blue-ink: #1c5cab;
  --bdg-green-bg: #e4f5e4;   --bdg-green-ink: #006300;
  --bdg-gray-bg: #f0efec;    --bdg-gray-ink: #52514e;
  --bdg-red-bg: #fbe9e9;     --bdg-red-ink: #a92f2f;

  /* Toast / 弹窗（反色表面，保证双主题高对比） */
  --toast-bg: #26251f;
  --toast-ink: #fcfcfb;
  --overlay: rgba(11, 11, 11, 0.45);

  --shadow-card: 0 1px 2px rgba(11, 11, 11, 0.04), 0 6px 20px -8px rgba(11, 11, 11, 0.08);
  --shadow-pop: 0 8px 32px -8px rgba(11, 11, 11, 0.22);

  --radius-lg: 14px;
  --radius-md: 10px;
  --radius-sm: 8px;
}

/* ---------- Design tokens：深色（跟随系统） ---------- */
@media (prefers-color-scheme: dark) {
  :root:where(:not([data-theme="light"])) {
    color-scheme: dark;

    --page: #0d0d0d;
    --surface-1: #1a1a19;
    --surface-2: #232321;
    --ink: #ffffff;
    --ink-2: #c3c2b7;
    --ink-3: #898781;
    --grid: #2c2c2a;
    --base: #383835;
    --border: rgba(255, 255, 255, 0.10);
    --border-strong: rgba(255, 255, 255, 0.20);

    --accent: #3987e5;
    --accent-strong: #5598e7;
    --accent-soft: rgba(57, 135, 229, 0.16);
    --accent-ink: #86b6ef;
    --focus-ring: rgba(57, 135, 229, 0.38);

    --series-1: #3987e5;
    --track: #184f95;          /* 蓝色阶 step 600 */

    --success-ink: #0ca30c;

    --bdg-amber-bg: rgba(250, 178, 25, 0.14); --bdg-amber-ink: #fab219;
    --bdg-blue-bg: rgba(57, 135, 229, 0.16);  --bdg-blue-ink: #86b6ef;
    --bdg-green-bg: rgba(12, 163, 12, 0.14);  --bdg-green-ink: #0ca30c;
    --bdg-gray-bg: rgba(255, 255, 255, 0.08); --bdg-gray-ink: #c3c2b7;
    --bdg-red-bg: rgba(224, 58, 58, 0.16);    --bdg-red-ink: #e66767;

    --toast-bg: #fcfcfb;
    --toast-ink: #0b0b0b;
    --overlay: rgba(0, 0, 0, 0.55);

    --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.30), 0 6px 20px -8px rgba(0, 0, 0, 0.50);
    --shadow-pop: 0 8px 32px -8px rgba(0, 0, 0, 0.60);
  }
}

